package config

import "fmt"

// ForwardsAll is the engine cap forwards value meaning the engine forwards
// all of its input types.
const ForwardsAll = "*"

type EngineCap struct {
	// Type of engine (one of "detection", "classification", "guidance", "position"
	// "generic", "filter")
	Type string `toml:"type"`
	// Input types supported by this engine
	Inputs []string `toml:"inputs"`
	// Input type forwarded by this engine, either one of its input types or
	// "*" for all of them (optional, defaults to "*")
	Forwards string `toml:"forwards,omitempty"`
	// Result type generated by this engine
	Result string `toml:"result,omitempty"`
}

// validate defaults forwards to all input types and checks that a specific
// forwarded type is one of the engine's input types.
func (e *EngineCap) validate() error {
	if e.Forwards == "" {
		e.Forwards = ForwardsAll
	}
	if e.Forwards != ForwardsAll && !e.MatchesInputType(e.Forwards) {
		return fmt.Errorf("engine cap forwards %q, which is not one of its inputs", e.Forwards)
	}
	return nil
}

// MatchesInputType checks whether an engine accepts the given input type.
func (e *EngineCap) MatchesInputType(inputType string) bool {
	for _, i := range e.Inputs {
		if i == inputType {
			return true
		}
	}
	return false
}

// MatchesForwardedType checks whether an engine forwards the given input type.
// An empty forwards value is treated as "*".
func (e *EngineCap) MatchesForwardedType(inputType string) bool {
	if e.Forwards == "" || e.Forwards == ForwardsAll {
		return e.MatchesInputType(inputType)
	}
	return e.Forwards == inputType
}

// MatchesResultType checks whether an engine generates the given result type.
func (e *EngineCap) MatchesResultType(resultType string) bool {
	return e.Result == resultType
}
